import { writable } from 'svelte/store';

const initialState = {
	visible: false,
	kind: null,
	title: 'Hints',
	description: 'Select a cell or use the toolbar to inspect the next step.',
	items: [],
	move: null,
	value: null,
};

function describeNextStepHint(hint) {
	if (!hint) {
		return {
			title: 'Next Step Hint',
			description: 'There is no forced next step on the board right now.',
		};
	}

	switch (hint.type) {
		case 'naked-single':
			return {
				title: 'Next Step Hint: Naked Single',
				description: 'This cell has only one valid candidate left, so you can fill it directly.',
			};
		case 'hidden-single-row':
			return {
				title: 'Next Step Hint: Hidden Single in Row',
				description: 'In this row, the value can go in only this one cell.',
			};
		case 'hidden-single-column':
			return {
				title: 'Next Step Hint: Hidden Single in Column',
				description: 'In this column, the value can go in only this one cell.',
			};
		case 'hidden-single-box':
			return {
				title: 'Next Step Hint: Hidden Single in Box',
				description: 'Inside this 3x3 box, the value fits only this one cell.',
			};
		default:
			return {
				title: 'Next Step Hint',
				description: 'A forced move is available on the current board.',
			};
	}
}

function createHintPanelStore() {
	const { subscribe, set } = writable(initialState);

	return {
		subscribe,
		showSelectHint(pos, candidates) {
			set({
				visible: true,
				kind: 'select',
				title: 'Selected Cell Hint',
				description: candidates && candidates.length > 0
					? 'These are the valid candidates for the selected cell.'
					: 'No candidate hint is available for the selected cell.',
				items: candidates ?? [],
				move: pos ? { x: pos.x, y: pos.y } : null,
				value: null,
			});
		},
		showNextStepHint(hint) {
			const content = describeNextStepHint(hint);

			set({
				visible: true,
				kind: 'next-step',
				title: content.title,
				description: content.description,
				items: hint ? [hint.value] : [],
				move: hint ? { x: hint.x, y: hint.y } : null,
				value: hint ? hint.value : null,
			});
		},
		clear() {
			set(initialState);
		},
	};
}

export const hintPanel = createHintPanelStore();